import{_ as p,a0 as o,w as u,s as r,I as s,x as a,a1 as e,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190725 How to Enable Canonical Kernel Livepatch Service on Ubuntu LTS System","title":"如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務","tag":"201907","desc":""},"relativePath":"201907/20190725 How to Enable Canonical Kernel Livepatch Service on Ubuntu LTS System.md","filePath":"[post].md"}'),d={name:"201907/20190725 How to Enable Canonical Kernel Livepatch Service on Ubuntu LTS System.md"};function c(h,n,b,g,k,x){const t=o("Link");return u(),r("div",null,[n[21]||(n[21]=s("h1",{id:"如何在-ubuntu-lts-系統上啓用-canonical-的內核實時補丁服務",tabindex:"-1"},[a("如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務 "),s("a",{class:"header-anchor",href:"#如何在-ubuntu-lts-系統上啓用-canonical-的內核實時補丁服務","aria-label":"Permalink to “如何在 Ubuntu LTS 系統上啓用 Canonical 的內核實時補丁服務”"},"​")],-1)),n[22]||(n[22]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/27/072251d3dij23lndtuutzr.jpg",alt:""})],-1)),n[23]||(n[23]=s("p",null,[a("Canonical 在 Ubuntu 14.04 LTS 系統中引入了"),s("ruby",null,[a("內核實時補丁服務"),s("rt",null,"Kernel Livepatch Service")]),a("。實時補丁服務允許你安裝和應用關鍵的 Linux 內核安全更新，而無需重新啓動系統。這意味着，在應用內核補丁程序後，你無需重新啓動系統。而通常情況下，我們需要在安裝內核補丁後重啓 Linux 服務器才能供系統使用。")],-1)),n[24]||(n[24]=s("p",null,"實時修補非常快。大多數內核修復程序只需要幾秒鐘。Canonical 的實時補丁服務對於不超過 3 個系統的用户無需任何費用。你可以通過命令列在桌面和服務器中啓用 Canonical 實時補丁服務。",-1)),n[25]||(n[25]=s("p",null,"這個實時補丁系統旨在解決高級和關鍵的 Linux 內核安全漏洞。",-1)),s("p",null,[n[1]||(n[1]=a("有關",-1)),e(t,{href:"https://wiki.ubuntu.com/Kernel/Livepatch"},{default:l(()=>[...n[0]||(n[0]=[a("支持的系統",-1)])]),_:1}),n[2]||(n[2]=a("和其他詳細信息，請參閲下表。",-1))]),n[26]||(n[26]=i('<div class="table-wrap"><table><thead><tr><th>Ubuntu 版本</th><th>架構</th><th>內核版本</th><th>內核變體</th></tr></thead><tbody><tr><td>Ubuntu 18.04 LTS</td><td>64-bit x86</td><td>4.15</td><td>僅 GA 通用和低電壓內核</td></tr><tr><td>Ubuntu 16.04 LTS</td><td>64-bit x86</td><td>4.4</td><td>僅 GA 通用和低電壓內核</td></tr><tr><td>Ubuntu 14.04 LTS</td><td>64-bit x86</td><td>4.4</td><td>僅 Hardware Enablement 內核</td></tr></tbody></table></div><p><strong>注意</strong>：Ubuntu 14.04 中的 Canonical 實時補丁服務 LTS 要求用户在 Trusty 中運行 Ubuntu v4.4 內核。如果你當前沒有運行使用該服務，請重新啓動到此內核。</p><p>為此，請按照以下步驟操作。</p><h3 id="如何獲取實時補丁令牌" tabindex="-1">如何獲取實時補丁令牌？ <a class="header-anchor" href="#如何獲取實時補丁令牌" aria-label="Permalink to “如何獲取實時補丁令牌？”">​</a></h3>',4)),s("p",null,[n[4]||(n[4]=a("導航到 ",-1)),e(t,{href:"https://auth.livepatch.canonical.com/"},{default:l(()=>[...n[3]||(n[3]=[a("Canonical 實時補丁服務頁面",-1)])]),_:1}),n[5]||(n[5]=a("，如果要使用免費服務，請選擇“Ubuntu 用户”。它適用於不超過 3 個系統的用户。如果你是 “UA 客户” 或多於 3 個系統，請選擇 “Ubuntu customer”。最後，單擊 “Get your Livepatch token” 按鈕。",-1))]),n[27]||(n[27]=i(`<p><img src="https://www.2daygeek.com/wp-content/uploads/2019/07/enable-canonical-livepatch-service-on-ubuntu-lts-system-1.jpg" alt=""></p><p>確保你已經在 “Ubuntu One” 中擁有帳號。否則，可以創建一個新的。</p><p>登錄後，你將獲得你的帳户密鑰。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/07/enable-canonical-livepatch-service-on-ubuntu-lts-system-2.jpg" alt=""></p><h3 id="在系統中安裝-snap-守護程序" tabindex="-1">在系統中安裝 Snap 守護程序 <a class="header-anchor" href="#在系統中安裝-snap-守護程序" aria-label="Permalink to “在系統中安裝 Snap 守護程序”">​</a></h3><p>實時補丁系統通過快照包安裝。因此，請確保在 Ubuntu 系統上安裝了 snapd 守護程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install snapd</span></span></code></pre></div><h3 id="如何系統中安裝和配置實時補丁服務" tabindex="-1">如何系統中安裝和配置實時補丁服務？ <a class="header-anchor" href="#如何系統中安裝和配置實時補丁服務" aria-label="Permalink to “如何系統中安裝和配置實時補丁服務？”">​</a></h3><p>通過運行以下命令安裝 <code>canonical-livepatch</code> 守護程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo snap install canonical-livepatch</span></span>
<span class="line"><span>canonical-livepatch 9.4.1 from Canonical* installed</span></span></code></pre></div><p>運行以下命令以在 Ubuntu 計算機上啓用實時內核補丁程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo canonical-livepatch enable xxxxc4xxxx67xxxxbxxxxbxxxxfbxx4e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Successfully enabled device. Using machine-token: xxxxc4xxxx67xxxxbxxxxbxxxxfbxx4e</span></span></code></pre></div><p>運行以下命令查看實時補丁機器的狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo canonical-livepatch status</span></span>
<span class="line"><span></span></span>
<span class="line"><span>client-version: 9.4.1</span></span>
<span class="line"><span>architecture: x86_64</span></span>
<span class="line"><span>cpu-model: Intel(R) Core(TM) i7-6700HQ CPU @ 2.60GHz</span></span>
<span class="line"><span>last-check: 2019-07-24T12:30:04+05:30</span></span>
<span class="line"><span>boot-time: 2019-07-24T12:11:06+05:30</span></span>
<span class="line"><span>uptime: 19m11s</span></span>
<span class="line"><span>status:</span></span>
<span class="line"><span>- kernel: 4.15.0-55.60-generic</span></span>
<span class="line"><span>  running: true</span></span>
<span class="line"><span>  livepatch:</span></span>
<span class="line"><span>    checkState: checked</span></span>
<span class="line"><span>    patchState: nothing-to-apply</span></span>
<span class="line"><span>    version: &quot;&quot;</span></span>
<span class="line"><span>    fixes: &quot;&quot;</span></span></code></pre></div><p>使用 <code>--verbose</code> 開關運行上述相同的命令，以獲取有關實時修補機器的更多信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo canonical-livepatch status --verbose</span></span></code></pre></div><p>如果要手動運行補丁程序，請執行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo canonical-livepatch refresh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Before refresh:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kernel: 4.15.0-55.60-generic</span></span>
<span class="line"><span>fully-patched: true</span></span>
<span class="line"><span>version: &quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>After refresh:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kernel: 4.15.0-55.60-generic</span></span>
<span class="line"><span>fully-patched: true</span></span>
<span class="line"><span>version: &quot;&quot;</span></span></code></pre></div><p><code>patchState</code> 會有以下狀態之一：</p><ul><li><code>applied</code>：未發現任何漏洞</li><li><code>nothing-to-apply</code>：成功找到並修補了漏洞</li><li><code>kernel-upgrade-required</code>：實時補丁服務無法安裝補丁來修復漏洞</li></ul><p>請注意，安裝內核補丁與在系統上升級/安裝新內核不同。如果安裝了新內核，則必須重新引導系統以激活新內核。</p><hr>`,22)),s("p",null,[n[7]||(n[7]=a("via: ",-1)),e(t,{href:"https://www.2daygeek.com/enable-canonical-kernel-livepatch-service-on-ubuntu-lts-system/"},{default:l(()=>[...n[6]||(n[6]=[a("https://www.2daygeek.com/enable-canonical-kernel-livepatch-service-on-ubuntu-lts-system/",-1)])]),_:1})]),s("p",null,[n[12]||(n[12]=a("作者：",-1)),e(t,{href:"https://www.2daygeek.com/author/magesh/"},{default:l(()=>[...n[8]||(n[8]=[a("Magesh Maruthamuthu",-1)])]),_:1}),n[13]||(n[13]=a(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...n[9]||(n[9]=[a("lujun9972",-1)])]),_:1}),n[14]||(n[14]=a(" 譯者：",-1)),e(t,{href:"https://github.com/wxy"},{default:l(()=>[...n[10]||(n[10]=[a("wxy",-1)])]),_:1}),n[15]||(n[15]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:l(()=>[...n[11]||(n[11]=[a("wxy",-1)])]),_:1})]),s("p",null,[n[18]||(n[18]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[16]||(n[16]=[a("LCTT",-1)])]),_:1}),n[19]||(n[19]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:l(()=>[...n[17]||(n[17]=[a("Linux中國",-1)])]),_:1}),n[20]||(n[20]=a(" 榮譽推出",-1))])])}const C=p(d,[["render",c]]);export{v as __pageData,C as default};
